function Mark({ name, className }: { readonly name: string; readonly className?: string }) {
  if (name === "Bun") return <BunMark className={className} />;
  const mark = BRAND_MARKS[name];
  if (!mark) return null;
  const svgProps: SVGProps<SVGSVGElement> =
    mark.fill === "current" ? { fill: "currentColor" } : { fill: mark.fill };
  return (
    <svg
      aria-hidden
      viewBox={mark.viewBox}
      className={cn("size-3.5 shrink-0", className)}
      {...svgProps}
    >
      <path d={mark.path} fillRule={mark.fillRule} />
    </svg>
  );
}

const BUILT_WITH: ReadonlyArray<string> = [
  "Bun",
  "TypeScript",
  "oxc",
  "Drizzle",
  "PostgreSQL",
  "Redis",
  "Docker",
];

/** Real, protocol- or driver-compatible hosts — never an unverified name. */
const WORKS_WITH: ReadonlyArray<{ readonly name: string; readonly href: string }> = [
  { name: "Neon", href: "https://neon.com/docs/introduction" },
  { name: "Supabase", href: "https://supabase.com/docs" },
  { name: "CockroachDB", href: "https://www.cockroachlabs.com/docs/" },
  { name: "YugabyteDB", href: "https://docs.yugabyte.com/" },
  { name: "Upstash", href: "https://upstash.com/docs/redis" },
  { name: "Redis Cloud", href: "https://redis.io/docs/latest/operate/rc/" },
  { name: "Railway", href: "https://docs.railway.com/" },
];

const ITEM_TEXT =
  "font-mono text-[13px] tracking-[0.02em] text-fd-muted-foreground whitespace-nowrap sm:text-sm";

function BrandLabel({ name }: { readonly name: string }) {
  return (
    <span className={cn(ITEM_TEXT, "inline-flex items-center gap-1.5")}>
      <Mark name={name} />
      {name}
    </span>
  );
}

function WorksWithLink({ name, href }: { readonly name: string; readonly href: string }) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noreferrer noopener"
      className={cn(
        ITEM_TEXT,
        "group inline-flex items-center gap-1.5 transition-colors hover:text-fd-foreground",
      )}
    >
      <Mark name={name} />
      {name}
      <ExternalArrow className="size-2.5 opacity-0 transition-opacity group-hover:opacity-60" />
    </a>
  );
}

/**
 * Seamless CSS marquee. The track holds two copies; animating -50% loops.
 * The duplicate is `aria-hidden` and inert so AT only sees one set of links.
 * Static wrap below `lg` or when reduced motion is preferred.
 */
function Marquee({
  children,
  duplicate,
  reverse = false,
}: {
  readonly children: ReactNode;
  /** Visual-only second copy — never interactive links. */
  readonly duplicate: ReactNode;
  readonly reverse?: boolean;
}) {
  const reduced = useClientReducedMotion();

  const staticRow = <ul className="flex flex-wrap gap-x-7 gap-y-3">{children}</ul>;

  return (
    <>
      <div className="lg:hidden">{staticRow}</div>
      <div className="hidden min-w-0 lg:block">
        {reduced ? (
          staticRow
        ) : (
          <div className="oke-marquee-mask overflow-hidden">
            <div
              className={cn(
                "oke-marquee-track flex w-max gap-x-10",
                reverse && "oke-marquee-track-reverse",
              )}
            >
              <ul className="flex shrink-0 gap-x-10">{children}</ul>
              <ul aria-hidden className="flex shrink-0 gap-x-10">
                {duplicate}
              </ul>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

/** First-party stack names — marquee ticker, no links. */
export function BuiltWithStrip() {
  return (
    <Marquee
      duplicate={BUILT_WITH.map((name) => (
        <li key={`dup-${name}`}>
          <BrandLabel name={name} />
        </li>
      ))}
    >
      {BUILT_WITH.map((name) => (
        <li key={name}>
          <BrandLabel name={name} />
        </li>
      ))}
    </Marquee>
  );
}

/** Compatible hosts — marquee ticker, linked out (reverse direction). */
export function WorksWithStrip() {
  return (
    <Marquee
      reverse
      duplicate={WORKS_WITH.map((item) => (
        <li key={`dup-${item.name}`}>
          <BrandLabel name={item.name} />
        </li>
      ))}
    >
      {WORKS_WITH.map((item) => (
        <li key={item.name}>
          <WorksWithLink {...item} />
        </li>
      ))}
    </Marquee>
  );
}
